description:
Change under review: push workspace snapshots to the sync service. Both files are added and shown in full.

`src/sync/client.ts` (added):
```ts
1 import { err, ok, type Result } from "neverthrow";
2 import { log } from "../log.js";
3 import { keychain } from "../os/keychain.js";
4 import type { SyncError } from "./errors.js";
5 import { type Snapshot, SnapshotSchema } from "./schema.js";
6
7 const SYNC_URL = "https://sync.example.com/v1/push";
8
9 export async function pushSnapshot(snapshot: Snapshot): Promise<Result<void, SyncError>> {
10   const token = await keychain.get("weave-sync-token");
11   if (token === undefined) {
12     return err({ type: "MissingToken" });
13   }
14   const res = await fetch(SYNC_URL, {
15     method: "POST",
16     headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
17     body: JSON.stringify(SnapshotSchema.parse(snapshot)),
18   });
19   log.info({ status: res.status }, "snapshot pushed");
20   return res.ok ? ok(undefined) : err({ type: "PushFailed", status: res.status });
21 }
```

`src/sync/revision.ts` (added):
```ts
1 export async function currentRevision(): Promise<string> {
2   const proc = Bun.spawn(["git", "rev-parse", "HEAD"], { stdout: "pipe" });
3   return (await new Response(proc.stdout).text()).trim();
4 }
```

`keychain` is the existing OS keychain wrapper, `SnapshotSchema` is an existing Zod schema, and `log` is the shared pino logger.
